// Redirects for NGINX, generated from redirects.mjs. Include it inside the server block:
//
//   server {
//       include /var/www/www.dannyvankooten.com/nginx-redirects.conf;
//   }
import redirects, { patternRedirects } from '../../redirects.mjs';

/** NGINX config strings can't contain unescaped whitespace, quotes, semicolons or braces. */
function nginxValue(value: string): string {
	return /[\s"';{}]/.test(value) ? `"${value.replace(/["\\]/g, '\\$&')}"` : value;
}

export function GET() {
	const lines = [
		'# Generated by src/pages/nginx-redirects.conf.ts from redirects.mjs',
		...Object.entries(redirects).map(([from, to]) => `location = ${nginxValue(from)} { return 301 ${nginxValue(to)}; }`),
		// Exact matches (location =) take precedence over these, regardless of order
		...patternRedirects.map(({ pattern, to }) => `location ~ ${nginxValue(pattern)} { return 301 ${nginxValue(to)}; }`),
		'',
	];

	return new Response(lines.join('\n'), {
		headers: { 'Content-Type': 'text/plain; charset=utf-8' },
	});
}
